      "fr": "Muhammad, Mehmet, Mamadou",
      "it": "Muhammad, Mehmet, Mamadou",
      "es": "Muhammad, Mehmet, Mamadou",
      "pt": "Muhammad, Mehmet, Mamadou",
      "ru": "Мухаммад, Мехмет, Мамаду",
      "uk": "Мухаммад, Мехмет, Мамаду",
      "ar": "محمد، مَهمت، مامادو",
